import React from 'react';

const About = () => {
    return (
        <div>
            <h1>About SoochnaPreneur</h1>
            <p>
                SoochnaPreneur is an initiative aimed at empowering individuals through information and resources. 
                Our mission is to provide access to vital information that can help entrepreneurs and communities thrive.
            </p>
            <h2>Our Objectives</h2>
            <ul>
                <li>To promote entrepreneurship and innovation.</li>
                <li>To provide resources and support for aspiring entrepreneurs.</li>
                <li>To create a network of partners and stakeholders committed to community development.</li>
                <li>To raise awareness about the importance of information access in driving economic growth.</li>
            </ul>
        </div>
    );
};

export default About;
